"""Generate Vim's colorscheme from the palettes and shared Neovim highlights."""
from pathlib import Path
import json
import re

ROOT = Path(__file__).resolve().parents[1]
source = (ROOT / 'lua/morello/init.lua').read_text(encoding='utf-8')
palettes = [json.loads((ROOT / name).read_text(encoding='utf-8'))
            for name in ('palette.json', 'palette-light.json')]
lines = [
    '" Generated by scripts/sync_vim.py. Requires Vim 8.2+ with truecolor or a GUI.',
    "if has('nvim')", "  lua require('morello').load()", '  finish', 'endif', '',
    "if !has('gui_running') && !exists('+termguicolors')",
    "  echoerr 'Morello requires a truecolor Vim build or a GUI'", '  finish', 'endif',
    "if exists('+termguicolors')", '  set termguicolors', 'endif',
    'unlet! g:colors_name', 'highlight clear', "if exists('syntax_on')", '  syntax reset', 'endif',
    "let g:colors_name = 'morello'", '',
]
for index, data in enumerate(palettes):
    lines.append("if &background ==# 'dark'" if index == 0 else 'else')
    lines += ['  let s:p = {']
    lines += [f"        \\ '{key}': '{color}'," for key, color in data['colors'].items()]
    lines += ['        \\ }', '  let g:terminal_ansi_colors = [']
    lines += ["        \\ " + ', '.join(f"'{color}'" for color in data['ansi'][i:i+4]) + ','
              for i in range(0, 16, 4)]
    lines += ['        \\ ]']
lines += ['endif', '',
    'function! s:hi(group, fg, bg, attrs, special) abort',
    "  execute 'highlight' a:group 'guifg=' . a:fg 'guibg=' . a:bg",
    "        \\ 'gui=' . a:attrs 'cterm=' . a:attrs 'guisp=' . a:special",
    'endfunction', '',
]

# Only named UI and syntax groups: Treesitter captures are Neovim-specific.
groups = re.findall(r'^    (\w+) = \{ (.+) \},$', source, re.M)
assert dict(groups)['Normal'] == 'fg = p.fg, bg = p.bg'
for name, text in groups:
    attrs = dict(part.split(' = ', 1) for part in text.split(', '))
    def value(key):
        raw = attrs.get(key)
        if raw is None:
            return "'NONE'"
        assert re.fullmatch(r'p\.\w+', raw), raw
        return 's:' + raw
    flags = [key for key in ('bold', 'underline', 'undercurl', 'strikethrough') if attrs.get(key) == 'true']
    style = "'" + (','.join(flags) if flags else 'NONE') + "'"
    if attrs.get('italic') == 'options.italic_comments':
        style = "(get(g:, 'morello_italic_comments', 0) ? 'italic' : 'NONE')"
    elif attrs.get('italic') == 'true':
        style = "'italic'"
    lines.append(f"call s:hi('{name}', {value('fg')}, {value('bg')}, {style}, {value('sp')})")
lines += ["call s:hi('Terminal', s:p.fg, s:p.bg, 'NONE', 'NONE')", '',
    'delfunction s:hi', 'unlet s:p', '']
(ROOT / 'colors/morello.vim').write_text('\n'.join(lines), encoding='utf-8', newline='\n')
print(f'Generated Vim colorscheme with {len(groups)} shared UI and syntax groups')
